```js
await (async () => { await page.keyboard.press('ArrowUp'); await page.keyboard.press('ArrowLeft'); await page.keyboard.press('Space'); return {count: await page.locator('#count').textContent(), steps: await page.locator('#steps').textContent(), log: await page.locator('#log').innerText()}; })(page);
```

### Result
{"count":"0 / 4","steps":"005","log":"The compass is trembling — treasure must be close.\n\nDay 1 — The island is quiet. Start exploring...\n\nTip: footprints fade, but buried gold doesn't."}
### Ran Playwright code
```js
await (async () => { await page.locator('#restart').click(); await page.keyboard.press('ArrowLeft'); for(let i=0;i<5;i++) await page.keyboard.press('ArrowUp'); await page.keyboard.press('ArrowLeft'); await page.keyboard.press('Space'); return {count: await page.locator('#count').textContent(),steps: await page.locator('#steps').textContent(),log: await page.locator('#log').innerText()}; })(page);
